            if __isarray(mats) then
                i = 0
                while (i < __len(mats)) do
                    cm.gainItem(mats[i], (-matQty[i]))
                    i = i + 1
                end
            else
                cm.gainItem(mats, (-matQty))
            end
            cm.gainMeso((-cost))
            cm.gainItem(item, 1)
            cm.sendOk("好了，鞋子做好了。走路小心別絆倒囉！")
        end
        cm.dispose()
    end
end
